import functools
import inspect
from typing import ForwardRef, Any, Dict, Callable
from fastapi.dependencies.utils import get_typed_signature, get_typed_annotation

# Mocking evaluate_forwardref as pydantic.typing.evaluate_forwardref
# Since we are in a test environment, we can just use a simple eval
def evaluate_forwardref(annotation, globalns, localns):
    if isinstance(annotation, ForwardRef):
        return eval(annotation.__forward_code__, globalns, localns)
    return annotation

# Redefining get_typed_annotation to use our mock evaluate_forwardref
def get_typed_annotation_mock(annotation: Any, globalns: Dict[str, Any]) -> Any:
    if isinstance(annotation, str):
        annotation = ForwardRef(annotation)
        annotation = evaluate_forwardref(annotation, globalns, globalns)
        if annotation is type(None):
            return None
    return annotation

def get_typed_signature_mock(call: Callable[..., Any]) -> inspect.Signature:
    signature = inspect.signature(call)
    globalns = getattr(call, "__globals__", {})
    typed_params = [
        inspect.Parameter(
            name=param.name,
            kind=param.kind,
            default=param.default,
            annotation=get_typed_annotation_mock(param.annotation, globalns),
        )
        for param in signature.parameters.values()
    ]
    typed_signature = inspect.Signature(typed_params)
    return typed_signature

# Test case
def create_test():
    # We need two different modules/globals
    # We can simulate this by creating a function in a different context

    # Module 1
    globals1 = {}
    class A:
        pass
    globals1['A'] = A

    def original_func(a: "A"):
        return a
    original_func.__globals__ = globals1

    # Module 2
    globals2 = {}

    def wrapper_func(a: "A"):
        return original_func(a)
    wrapper_func.__globals__ = globals2

    # Wrap it
    wrapper_func = functools.wraps(original_func)(wrapper_func)

    # Now wrapper_func.__wrapped__ is original_func.
    # wrapper_func.__globals__ is globals2 (no 'A')
    # original_func.__globals__ is globals1 (has 'A')

    try:
        sig = get_typed_signature_mock(wrapper_func)
        print("Success!")
    except NameError as e:
        print(f"Caught expected NameError: {e}")

create_test()
