from __future__ import annotations
import functools
import typing
import inspect

class A:
    pass

def original_func(a: A):
    return a

def create_wrapper():
    @functools.wraps(original_func)
    def wrapper_func(a: A):
        return original_func(a)
    return wrapper_func

# Now we have wrapper_func defined in a different scope (inside create_wrapper)
# and it's wrapped.
wrapper = create_wrapper()

try:
    # typing.get_type_hints should handle this correctly by looking at __wrapped__
    hints = typing.get_type_hints(wrapper)
    print(f"Hints: {hints}")
except Exception as e:
    print(f"Caught exception: {type(e).__name__}: {e}")

# Now let's see what get_typed_signature does
from fastapi.dependencies.utils import get_typed_signature
try:
    sig = get_typed_signature(wrapper)
    print(f"Signature: {sig}")
    for param in sig.parameters.values():
        print(f"Param {param.name} annotation: {param.annotation}")
except Exception as e:
    print(f"Caught exception: {type(e).__name__}: {e}")
EOF

